// Single data layer for the site. Today it reads the bundled demo dataset
// (funds.json, generated by scripts/generate-data.mjs); the async functions
// keep the same signatures when it is replaced by a real Gemel-Net / API source.
import DATA from './funds.json';

const FUNDS = DATA.funds;
const BY_ID = new Map(FUNDS.map((f) => [f.id, f]));

export async function getMeta() {
  return DATA.meta;
}

export async function getCompanies() {
  return DATA.companies;
}

export async function getFunds() {
  return FUNDS;
}

export async function getFund(id) {
  return BY_ID.get(id) || null;
}

export async function getFundsByIds(ids = []) {
  return ids.map((id) => BY_ID.get(id)).filter(Boolean);
}

/** Instant search for the search box: name, company, track or product. */
export function searchFundsSync(q, limit = 8) {
  const terms = String(q || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  return FUNDS
    .filter((f) => {
      const hay = `${f.name} ${f.company} ${f.track} ${f.productName}`.toLowerCase();
      return terms.every((t) => hay.includes(t));
    })
    .slice(0, limit);
}

/** Highest last-month return, optionally within one product ('all' for every product). */
export function topThisMonthSync(product = 'all', limit = 6) {
  return FUNDS
    .filter((f) => product === 'all' || f.product === product)
    .slice()
    .sort((a, b) => b.returns.m1 - a.returns.m1)
    .slice(0, limit);
}

// Website product ids -> topics understood by POST /api/contact.
const TOPIC = { gemel: 'gemel', hishtalmut: 'hishtalmut', pension: 'pension', policy: 'other' };

/** Send a lead to the server (POST /api/contact). Resolves to { ok, waUrl } or { ok: false }. */
export async function submitLead({ name, phone, email, product, notes, context, source }) {
  const message = [notes, context && !String(notes || '').includes(context) ? `הקשר: ${context}` : '', source ? `מקור: ${source}` : '']
    .filter(Boolean)
    .join('\n');
  try {
    const res = await fetch('/api/contact', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, phone, email, topic: TOPIC[product] || 'other', message }),
    });
    const body = await res.json().catch(() => ({}));
    return res.ok ? body : { ok: false, error: body.error || 'שגיאה בשליחה' };
  } catch {
    return { ok: false, error: 'אין חיבור לשרת' };
  }
}
